import hashlib,json,shutil,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'round3'))
from core import ROOT,read_prompt,digest
from round3.runtime import body_for
from round3 import repeat
OUT=ROOT/'round4'
def pct(x):return 'n/a' if x is None else f'{100*x:.1f}%'
def hit(m):return f"{m['tp']+m['tn']}/{m['n']} ({pct(m['agreement'])})"
if __name__=='__main__':
 repeat.OUT=OUT;stability=repeat.check()
 reports=json.loads((OUT/'test_results.json').read_text());selection=json.loads((OUT/'selection.json').read_text());goal=json.loads((OUT/'goal_assessment.json').read_text());comparison=json.loads((OUT/'comparison.json').read_text());protocol=json.loads((OUT/'protocol.json').read_text());audit=json.loads((OUT/'fresh_audit.json').read_text());prompt=read_prompt(OUT/'best_candidate.py')
 assert digest(prompt)==reports['selected']['prompt_hash']==selection['selected']['prompt_hash']
 budget=json.loads((ROOT/'cache/budget.json').read_text());costs={k:{'conservative_total':v+sum(x['amount'] for x in budget['pending'].values() if x['provider']==k),'limit':budget['limits'][k]} for k,v in budget['spent'].items()};assert all(v['conservative_total']<=v['limit'] for v in costs.values())
 uncertainty=json.loads((OUT/'uncertainty.json').read_text())
 results={'uncertainty':uncertainty,'round':'round4','protocol':protocol,'selected':selection['selected'],'test':{name:{k:v for k,v in r.items() if k!='predictions'} for name,r in reports.items()},'comparison':comparison,'goal_assessment':goal,'repeatability':stability,'budget_session':costs,'fresh_audit':audit}
 for name in ['best_candidate.py','best_prompt.txt','inference_system.txt','selection.json']:shutil.copyfile(OUT/name,ROOT/name)
 for path in [OUT/'results.json',ROOT/'results.json']:path.write_text(json.dumps(results,indent=2))
 (ROOT/'request_template.json').write_text(json.dumps(body_for(prompt,'REPLACE WITH THE ENGLISH TEXT TO CLASSIFY','default'),ensure_ascii=False,indent=2));(ROOT/'inference_config.json').write_text(json.dumps({'mode':'default','prompt_hash':digest(prompt)},indent=2))
 manifest={'active_round':'round4','model':'anthropic/claude-opus-5.5','teacher_requested':'pangram-4','teacher_returned':sorted({json.loads(l)['teacher_version'] for l in (OUT/'test.jsonl').read_text().splitlines()}),'selected_prompt_hash':digest(prompt),'inference_mode':'default','tokenizer':'o200k_base','shinka_commit':'8adc053a2ce4511ad2ac310e004c530a73fb974a','source_git_commit':'388cbe3b6c37d5175b9f460015bb092ef9e34894','dataset_files':{name:{'sha256':hashlib.sha256((OUT/(name+'.jsonl')).read_bytes()).hexdigest(),'rows':len((OUT/(name+'.jsonl')).read_text().splitlines())} for name in ['train','test','prior']}};(ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2))
 old,new=reports['previous'],reports['selected']
 lines=['# Pangram imitation with Opus 5.5 — round 4','',f"Fresh test: **{hit(new['overall'])}**, balanced accuracy **{pct(new['overall']['balanced_accuracy'])}**. Operational target: **{'MET on this sample' if goal['met'] else 'NOT MET'}**.",'','This measures agreement with Pangram 4 (returned version 4.1), not true authorship or writing quality. The selected prompt is the train-selected candidate; the fresh test never selects it. Small strata and correlated variants limit generalization claims.','',
 'The full pairwise rulebook from [anti-slop, commit 388cbe3](https://github.com/miqdadbadjuber/anti-slop/blob/388cbe3b6c37d5175b9f460015bb092ef9e34894/skills/antislop-copywriting/SKILL.md) and an independent Opus advisor were incorporated in round 3. Source pairwise results are not Pangram-imitation results. Provenance, MIT license and earlier procedure: [round 3 report](round3/REPORT.md).','',
 f"Round 3 independent test scored 131/142, balanced accuracy 94.1%, with all 48 positives detected and 11 false positives. Those 142 cases are now explicitly TRAINING, plus {protocol['preservation_controls']} controls. Shinka performed baseline plus up to two mutations on {protocol['train_n']} training cases. Rules may change but labeled references stay fixed; full sample copying is rejected. Runtime remains provider-default reasoning with strict schema and a cached system prefix. No fresh test outcomes were supplied to the optimizer.",'',
 f"New test: {audit['n']} unique texts, {audit['groups']} new document/topic groups; exact and near duplicates checked against {audit['old_rows']} prior rows. Human documents, six generator models, plain/light/antislop rewrites, Markdown-only and human/AI mixtures. There are {audit['raw_n']-audit['n']} deduplicated variants. Length uses o200k_base, a proxy rather than Opus's proprietary tokenizer. Pangram recommends at least 50 words; very short results imitate API behavior outside that recommendation.",'',
 '| Metric | Previous round | Selected |','|---|---:|---:|',f"| Agreement | {hit(old['overall'])} | {hit(new['overall'])} |",f"| Balanced accuracy | {pct(old['overall']['balanced_accuracy'])} | {pct(new['overall']['balanced_accuracy'])} |",f"| False positive | {old['overall']['fp']} | {new['overall']['fp']} |",f"| False negative | {old['overall']['fn']} | {new['overall']['fn']} |",f"| Unavailable (counted as errors) | {old['overall']['unavailable']} | {new['overall']['unavailable']} |",f"| Under 200 tokens | {hit(old['under200'])} | {hit(new['under200'])} |"]
 for field in ['bucket','origin','model','scenario']:
  lines+=['',f'| {field} | Previous | Selected | Selected balanced accuracy |','|---|---:|---:|---:|']
  for k,m in new['by_'+field].items():lines.append(f"| {k} | {hit(old['by_'+field][k])} | {hit(m)} | {pct(m['balanced_accuracy'])} |")
 lo,hi=comparison['group_bootstrap_delta95'];lines+=['',f"Corrected {comparison['improved']} errors; introduced {comparison['regressed']}. Exploratory group-bootstrap 95% interval for balanced-accuracy change: [{100*lo:.1f}, {100*hi:.1f}] percentage points. This includes sampling uncertainty, not future-model guarantees.",'',f"Repeatability diagnostic: {stability['stable_cases']}/{stability['n']} preselected cases stable across three calls; unavailable calls {stability['unavailable_calls']}. Failed operational checks: {', '.join(goal['failed']) or 'none'}. Thresholds were retained unchanged from round 3.",'','## Use','','From `pangram_opus`, with OPENROUTER_API_KEY in the environment:','','```sh','.venv/bin/python classify.py example.txt','```','','Returns `{"slop": true}` or `{"slop": false}`. Provider refusal is an error (exit 2), never silently human. `best_prompt.txt` is the calibrated prompt; `inference_system.txt` includes the contract; `request_template.json` and `inference_config.json` reproduce runtime. One classified text per request.','', 'Full artifacts: `round4/selection.json`, `round4/test_results.json`, `round4/results.json`, `round4/goal_assessment.json`. Prior working artifacts are backed up with `round4/previous_`. Corpus provenance is retained; Brown noncommercial research and source terms continue to apply.','', '## Cumulative budget','']
 for k,v in costs.items():lines.append(f"- {k}: conservative ${v['conservative_total']:.2f} / ${v['limit']:.0f}, including margin and pending reservations.")
 lines+=['','The same session ledger is used throughout; do not reset it. Pangram costs are estimated from billed-word units, not a bank statement. API keys are not stored in artifacts.']
 lines+=['', 'Exploratory group-bootstrap 95% intervals for the selected classifier: agreement '+str([round(100*x,1) for x in uncertainty['agreement95']])+'%; balanced accuracy '+str([round(100*x,1) for x in uncertainty['balanced_accuracy95']])+'%. The operational thresholds concern point estimates; these intervals show their uncertainty.']
 for p in [ROOT/'README.md',OUT/'REPORT.md']:p.write_text('\n'.join(lines)+'\n')
 print(json.dumps({'selected':new['overall'],'goal_met':goal['met'],'budget':costs},indent=2))
